+// Sites: the kitchens Larder serves. Every location belongs to one site;
+// batches belong to the site of their location. Items, suppliers, recipes and
+// dishes are shared by all sites.
+import { AppError } from "../errors.js";
+
+/** The site used when a caller names none. */
+export const DEFAULT_SITE = "main";
+
+/** Every site, in list order. */
+export function listSites(store) {
+  return [...(store.data.sites ?? [])];
+}
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** The site a location belongs to (locations not in the list count as the default site). */
+export function siteOfLocation(store, locationId) {
+  return store.data.locations.find((l) => l.id === locationId)?.site ?? DEFAULT_SITE;
+}
+
+/** Whether a location exists and belongs to `site`. */
+export function locationInSite(store, locationId, site = DEFAULT_SITE) {
+  return store.data.locations.some((l) => l.id === locationId && l.site === site);
+}
+
+/** The batches stored at `site`. */
+export function siteBatches(store, site = DEFAULT_SITE) {
+  return store.data.batches.filter((b) => siteOfLocation(store, b.location) === site);
+}
