@@ -0,0 +1,76 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const annex = { "X-Larder-Site": "annex" };
+
+test("requests without a site header use site main", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items/1" });
+  assert.equal(res.body.onHand, 10);
+  assert.equal(res.body.batches.length, 2);
+});
+
+test("an unknown site is a 400 with its own code", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "x-larder-site": "attic" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+  assert.match(res.body.error.message, /attic/);
+});
+
+test("stock, batches, reports and alerts only see the request's site", async () => {
+  const { handle } = app();
+  const items = (await handle({ path: "/items", headers: annex })).body;
+  assert.equal(items.length, 6);
+  assert.ok(items.every((i) => i.onHand === 0));
+  assert.deepEqual((await handle({ path: "/batches", headers: annex })).body, []);
+  assert.equal((await handle({ path: "/batches/1", headers: annex })).status, 404);
+  assert.equal((await handle({ method: "POST", path: "/batches/6/waste", headers: annex, body: { qty: 1 } })).status, 404);
+  assert.equal((await handle({ path: "/reports/stock-value", headers: annex })).body.totalCents, 0);
+  const alerts = (await handle({ path: "/alerts", headers: annex })).body;
+  assert.deepEqual(alerts.expiring, []);
+  assert.equal(alerts.lowStock.length, 6);
+  assert.deepEqual((await handle({ path: "/suppliers", headers: annex })).body.length, 2);
+});
+
+test("cooking uses only the request's site", async () => {
+  const { handle, store } = app();
+  const before = JSON.stringify(store.data.batches);
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", headers: annex, body: { portions: 1 } });
+  assert.equal(res.status, 409);
+  assert.equal(JSON.stringify(store.data.batches), before);
+});
+
+test("orders are received into the request's site", async () => {
+  const { handle, store } = app();
+  const wrong = await handle({ method: "POST", path: "/orders/2/receive", headers: annex, body: { lots: [{ lot: "A", expires: null, location: "fridge" }, { lot: "B", expires: null, location: "fridge" }] } });
+  assert.equal(wrong.status, 400);
+  assert.equal(wrong.body.error.code, "unknown_location");
+  const ok = await handle({ method: "POST", path: "/orders/2/receive", headers: annex, body: { lots: [{ lot: "A", expires: "2026-11-05", location: "annex-fridge" }, { lot: "B", expires: null, location: "annex-fridge" }] } });
+  assert.equal(ok.status, 200);
+  const milk = (await handle({ path: "/items/2", headers: annex })).body;
+  assert.equal(milk.onHand, 12);
+  assert.equal((await handle({ path: "/items/2" })).body.onHand, 10);
+  assert.ok(store.data.batches.some((b) => b.location === "annex-fridge"));
+});
+
+test("stock-takes only see the request's site", async () => {
+  const { handle } = app();
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", headers: annex, body: { location: "dry" } })).status, 400);
+  const take = (await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: annex })).status, 404);
+  const annexTake = await handle({ method: "POST", path: "/stocktakes", headers: annex, body: { location: "annex-fridge" } });
+  assert.equal(annexTake.status, 201);
+  const count = await handle({ method: "POST", path: `/stocktakes/${annexTake.body.id}/counts`, headers: annex, body: { batchId: 3, counted: 1 } });
+  assert.equal(count.status, 404);
+});
+
+test("the nightly job checks every site", async () => {
+  const { handle, store } = app();
+  await handle({ method: "POST", path: "/jobs/nightly" });
+  const low = store.data.outbox.filter((m) => m.kind === "low_stock");
+  assert.deepEqual(low.map((m) => m.key), ["low:annex:2026-10-28"]);
+  assert.match(low[0].subject, /Annex kitchen/);
+  assert.ok(store.data.outbox.some((m) => m.key === "expiry:2026-10-28:4"));
+});
